// Function to get the value at a given index in an array
int getValueFromArray(int arr[], int size, int index) {
    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    int size, index;
    int *arr;

    // Read the size of the array
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    if (size <= 0) {
        fprintf(stderr, "Invalid array size.\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for the array
    arr = (int *)malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Read the elements of the array
    printf("Enter the elements of the array:\n");
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Read the index to get the value from the array
    printf("Enter the index to retrieve the value: ");
    scanf("%d", &index);

    // Call getValueFromArray and store the result
    int result = getValueFromArray(arr, size, index);

    // Free the allocated memory
    free(arr);

    // Return the result as the exit code
    return result;
}
```

### Explanation:

1. **Function `getValueFromArray`**:
   - This function takes an array of integers (`arr`), its size (`size`), and an index (`index`) as parameters.
