    // Generate three random integers larger than 1000
    int a = rand() % 9001 + 1000; // Generates a number between 1000 and 10000
    int b = rand() % 9001 + 1000; // Generates a number between 1000 and 10000
    int c = rand() % 9001 + 1000; // Generates a number between 1000 and 10000

    // Print the three integers
