    // Open the file in read mode
    file = fopen(FILE_PATH, "r");

    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    // Read and print each character from the file until the end of the file is reached
    while ((ch = fgetc(file)) != EOF) {
