int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Generate three random floats between 0.0 and 1.0
    float random1 = (float)rand() / RAND_MAX;
    float random2 = (float)rand() / RAND_MAX;
    float random3 = (float)rand() / RAND_MAX;

    // Convert the floats to strings
    char str1[50];
    char str2[50];
    char str3[50];

    snprintf(str1, sizeof(str1), "%.2f", random1);
    snprintf(str2, sizeof(str2), "%.2f", random2);
    snprintf(str3, sizeof(str3), "%.2f", random3);

    // Concatenate the strings into a single string
    char result[150];
    snprintf(result, sizeof(result), "%s, %s, %s", str1, str2, str3);

    // Write the resulting string to a file
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return 1;
    }

    if (fprintf(file, "%s", result) < 0) {
        fprintf(stderr, "Error writing to file\n");
