#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void trimTrailingWhitespace(char *str) {
    size_t len = strlen(str);
    while (len > 0 && str[len - 1] == ' ') {
        str[--len] = '\0';
    }
}

void trimNewLines(char *str) {
    size_t len = strlen(str);
    while (len > 0 && (str[len - 1] == '\n' || str[len - 1] == '\r')) {
        str[--len] = '\0';
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <string>\n", argv[0]);
        return 1;
    }

    if (!argv[1]) {
        fprintf(stderr, "Argument is a null pointer.\n");
        return 1;
    }

    char *input = argv[1];

    // Trim trailing whitespace
    trimTrailingWhitespace(input);

    // Trim new lines
    trimNewLines(input);

    // Null terminate the string (although it should already be null terminated)
    input[strlen(input)] = '\0';

    printf("Trimmed string: %s\n", input);

    return 0;
}
```

### Explanation:
